                    <span class="icon">🔍</span> Padrão 5 a remover
                </label>
                <input type="text" id="pattern5" class="pattern-input" placeholder="Seu padrão personalizado...">
            </div>
        </div>

        <button class="btn-remove" onclick="processarTexto()">
            <span class="icon">✨</span> Processar e Remover Textos
        </button>

        <div class="result-area" id="resultArea">
