    </div>

    <script>
        function processarTexto() {
            const texto = document.getElementById('mainText').value.trim();
            if (!texto) {
                alert('⚠️ Cole primeiro o texto principal no campo indicado!');
                return;
            }

            // Valida que todos os 5 padrões foram preenchidos
            const padroes = [
                document.getElementById('pattern1').value.trim(),
                document.getElementById('pattern2').value.trim(),
                document.getElementById('pattern3').value.trim(),
                document.getElementById('pattern4').value.trim(),
                document.getElementById('pattern5').value.trim()
            ];

            const vazios = padroes.filter(p => p.length === 0);
            if (vazios.length > 0) {
                const nomes = ['Padrão 1', 'Padrão 2', 'Padrão 3', 'Padrão 4', 'Padrão 5'];
                let msg = '';
                vazios.forEach((v, i) => {
                    msg += `${nomes[i]} obrigatório. \n`;
                });
                alert(`⚠️ Os seguintes campos estão vazios:\n${msg}`);
                return;
            }

            let resultado = texto;

            // Remove cada padrão usando regex global
            padroes.forEach((padrao, indice) => {
                if (padrao) {
                    // Cria regex case-insensitive para símbolos comuns
                    const flags = padrao.includes('.') || padrao.includes('*') ? '' : 'gi';
                    // Escapa caracteres especiais para usar como literal se necessário
                    // Mas vamos permitir regex avançada
                    try {
                        const regex = new RegExp(padrao.replace(/[.*+?^${}()|[\]\\]/g, '\\$&'), flags);
                        resultado = resultado.replace(regex, '');
                    } catch (e) {
                        // Se falhar, trata como string literal
                        const escape = str => str.replace(/[.*+?^${}()|[\]\\]/g, c => 
                            {'\\': '\\\\', '.': '\\.', '+': '\\+', '?': '\\?', '^': '\\^', '$': '\\$', '(': '\\(', ')': '\\)', '|': '\\|', '[': '\\[', ']': '\\]', '\\': '\\\\'}[c]
                        );
                        const literal = `(${escape(padrao)})`;
                        resultado = resultado.replace(new RegExp(literal, 'gi'), '');
                    }
                }
            });

            // Atualiza resultados
            document.getElementById('resultText').value = resultado;

            document.getElementById('statOriginal').textContent = texto.length;
            document.getElementById('statLimpo').textContent = resultado.length;

            const resultArea = document.getElementById('resultArea');
            const emptyMsg = document.getElementById('emptyMsg');

            if (resultado === texto) {
                resultArea.style.display = 'block';
                emptyMsg.className = 'empty-msg highlighted';
                emptyMsg.textContent = '✅ Nenhum dos padrões encontrados! Texto permanece intacto.';
            } else {
                resultArea.style.display = 'block';
                emptyMsg.style.display = 'none';
            }
        }

        function copiarResultado() {
            const texto = document.getElementById('resultText').value;
            if (!texto) return;

            navigator.clipboard.writeText(texto).then(() => {
                const btn = document.getElementById('copyBtn');
                btn.classList.add('copied');

                setTimeout(() => {
                    btn.classList.remove('copied');
                }, 2000);
            }).catch(err => {
                alert('Não foi possível copiar: ' + err.message);
            });
        }
    </script>
